};

post-user-login:
// Code Action sandbox API. Calls are recorded and applied after the handler completes; methods return no result.

interface ActionClaimAPI {
    /** Values must be JSON serializable. Reserved token claims cannot be set. */
    setCustomClaim(claim: string, value: unknown): void;
}

interface ActionAccessAPI {
    /** Deny with an error code and an optional human-readable reason. */
    deny(code: string, reason?: string): void;
}

interface ActionRedirectAPI {
    /** Query values are appended to the URL; they must be strings. */
    sendUserTo(url: string, options?: {
        query?: Record<string, string>;
    }): void;
}

interface ActionLinkAPI {
    /** Records a link request; does not return a user or immediately mutate event.user. */
    setLinkedTo(primaryUserId: string): void;
}

interface ActionUsersAPI {
    /**
     * Creates the user `<connection>|<id>` if missing, otherwise merges the
     * profile and app_metadata into it. Returns nothing: link to it with
     * `api.user.setLinkedTo("<connection>|<id>")`.
     */
    ensure(params: ActionEnsureUserParams): void;
}

interface ActionEnsureUserParams {
    /** Name of an `external` connection with `allow_action_users` enabled. */
    connection: string;
    /** The key in the external system. The user_id becomes `<connection>|<id>`. */
    id: string;
    /** Blank fields are ignored; present fields overwrite on an existing user. */
    profile?: ActionEnsureUserProfile;
    /** Shallow-merged into the user's app_metadata. Must be JSON serializable. */
    app_metadata?: Record<string, unknown>;
}

interface ActionEnsureUserProfile {
    email?: string;
    email_verified?: boolean;
    phone_number?: string;
    name?: string;
    given_name?: string;
    family_name?: string;
    nickname?: string;
    picture?: string;
}

interface ActionMultifactorAPI {
    /**
     * Require MFA for this login with any factor the tenant has enabled.
     * `"none"` never removes MFA required by the tenant policy or another action.
     */
    enable(provider: string, options?: ActionMultifactorEnableOptions): void;
}

interface ActionMultifactorEnableOptions {
    /** Recorded with the request; remembering the browser is not supported yet. */
    allowRememberBrowser?: boolean;
}

type ActionAPI = {
    accessToken: ActionClaimAPI;
    idToken: ActionClaimAPI;
    access: ActionAccessAPI;
    prompt: {
        render(formId: string): void;
    };
    redirect: ActionRedirectAPI;
    user: ActionLinkAPI;
    users: ActionUsersAPI;
    multifactor: ActionMultifactorAPI;
};

